import 'package:flutter/material.dart';import '../models/menu_item.dart';import '../theme.dart';class MenuItemCard extends StatelessWidget {  final MenuItem item;  final VoidCallback? onAdd;  const MenuItemCard({super.key, required this.item, this.onAdd});  @override  Widget build(BuildContext context) {    return Card(      margin: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),      elevation: 2,      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(10)),      child: ListTile(        leading: Image.network(item.image, width: 60, fit: BoxFit.cover),        title: Text(item.name, style: TextStyle(color: AppTheme.textDark)),        subtitle: Text('${item.price.toStringAsFixed(2)} DT'),        trailing: onAdd != null            ? IconButton(          icon: const Icon(Icons.add_shopping_cart, color: AppTheme.secondary),          onPressed: onAdd,        )            : Text("Unavailable", style: TextStyle(color: AppTheme.textMedium)),      ),    );  }}